INSERT INTO public."seo_metadata" ("id", "page_key", "title", "description", "keywords", "og_title", "og_description", "og_image", "canonical_url", "language", "status", "imported_at", "created_by", "created_at", "updated_at", "content", "user_id", "template_id", "sections_data", "seo_h1", "seo_h2", "daisy_theme_slug", "folder") VALUES ('8e15776c-fe48-437c-9eaf-f53bb9ed1ba0', 'testelite-copie-mmdoycwm', 'Maîtrisez l''art de parler en public (copie)', 'Devenez l''orateur que tout le monde écoute. Méthode neuroscientifique exclusive pour parler en public avec aisance et conviction.', ARRAY[]::text[], NULL, NULL, NULL, NULL, 'fr', 'published', '2026-03-05T12:23:41.697+00:00', NULL, '2026-03-05T16:39:55.920899+00:00', '2026-03-05T18:04:21.531+00:00', NULL, '1e3aa8cc-2165-45da-b14a-d7993937454c', '3787f344-0ff4-49be-868a-8526f6849ef4', '[{"id":"section-1771740092479","type":"header","order":0,"design":{"colors":{"buttonText":"#ffffff","buttonShadow":"0 2px 6px rgba(0, 0, 0, 0.12)","sectionRadius":"0px","buttonBackground":"#000000","buttonBorderColor":"#111827","buttonBorderStyle":"solid","buttonBorderWidth":"1px"},"spacing":{"marginTop":"0px","paddingTop":"0px","marginBottom":"0px","paddingBottom":"0px"},"background":{"type":"transparent","value":"","backdropBlur":"2px","backdropColor":"#ffffff","backdropOpacity":0},"typography":{"linkColor":"#dbe3f5","headingColor":"#c4d6fd"}},"content":{"logo":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1771740059335-e9spj.webp","ctaLink":"","ctaText":"Je découvre la méthode","cartLink":"#","logoText":"Éloquence Élite","navItems":[{"link":"#methode","label":"La méthode"},{"link":"#fonctionnalites","label":"Fonctionnalités"},{"link":"#profils","label":"Profils"},{"link":"#faq","label":"FAQ"}],"showCart":false,"searchLink":"#","showSearch":true,"accountLink":"#","accountText":"Log in","secondaryCtaLink":"#","secondaryCtaText":"Book a call"},"variant":"transparent","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeRef":"none","themeMode":"named"}},{"id":"section-1771740560305","type":"hero","order":1,"design":{"media":{"imageRadius":"0px"},"colors":{"accent":"#f5f5f5","buttonText":"#111827","buttonBackground":"#f5f5f5"},"layout":{"contentPosition":"left"},"overlay":{"enabled":false},"spacing":{"marginTop":"0px","paddingTop":"96px","marginBottom":"0px","paddingBottom":"96px"},"background":{"type":"image","value":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772267162039-bgqcfl.jpg","opacity":1,"overlayColor":"#000829","overlayOpacity":0.55},"typography":{"textColor":"#d1d5db","h1FontFamily":"''Lora'', serif","headingColor":"#f5f5f5"}},"content":{"image":"","ctaLink":"","ctaText":"Je découvre la méthode","headline":"Maîtrisez l''art de parler en public : La méthode pour captiver et convaincre","subheadline":"Devenez l''orateur que tout le monde écoute grâce à notre stratégie exclusive. Faites enfin l''expérience d''une transformation radicale où votre expertise rencontre une éloquence absolue pour parler en public sans la moindre hésitation."},"variant":"default","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771741194298","type":"logocloud","order":2,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"64px","marginBottom":"0px","paddingBottom":"64px"},"background":{"type":"image","value":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772267173011-1pfbf.jpg","opacity":0.45},"typography":{}},"content":{"logos":[{"url":"","name":"Maîtrise de la Voix"},{"url":"","name":"Gestuelle & Posture"},{"url":"","name":"Structure Narrative"},{"url":"","name":"Gestion du Stress"},{"url":"","name":"Rhétorique Moderne"},{"url":"","name":"Éloquence Digitale"}],"title":"Les piliers de votre maîtrise oratoire","subtitle":"Une formation complète qui couvre toutes les dimensions de la prise de parole d''élite"},"variant":"grid","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771741678521","type":"split-content-checklist","order":3,"design":{"media":{"imageRadius":"0px"},"colors":{"accent":"#f7f7f7","iconColor":"#bfbfbf","buttonText":"#ffffff","buttonRadius":"2px","iconBackground":"#F3F4F6","iconBorderColor":"#D1D5DB","buttonBackground":"#d4d4d4"},"spacing":{"marginTop":"0px","paddingTop":"20px","marginBottom":"0px","paddingBottom":"20px"},"background":{"type":"image","value":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772267189495-j0w2ri.jpg"},"typography":{"h1Color":"#ffffff","h2Color":"#ffffff","linkColor":"#d1d1d1","textColor":"#bcbfc2","headingColor":"#ffffff","subtitleColor":"#ebebeb"}},"content":{"image":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772267189495-j0w2ri.jpg","title":"Le passage de l''ombre à la lumière — En finir avec le trac paralysant","divider":true,"checklist":["Déconstruire vos blocages internes grâce à la neuroscience","Libérer un leadership naturel et percutant en toute situation","Diriger le regard de votre auditoire avec une sérénité absolue"],"description":"Imaginez un instant que vous puissiez parler en public avec la même aisance que lors d''une discussion entre amis proches. Notre approche neuroscientifique déconstruit vos blocages internes pour libérer un leadership naturel et percutant. Vous ne subissez plus le regard des autres, vous le dirigez avec une sérénité totale."},"variant":"default","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeMode":"inherit"}},{"id":"section-1771751403903","type":"stats","order":4,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"stats":[{"label":"Pour ressentir une bascule psychologique majeure","number":"10","suffix":"h"},{"label":"Du succès se joue avant d''entrer dans la salle","number":"80","suffix":"%"},{"label":"De force perdue sans contact visuel avec l''audience","number":"80","suffix":"%"},{"label":"Pour constater des progrès majeurs dès le départ","number":"1","suffix":"re séance"}],"title":"Votre progression en chiffres","subtitle":"Des résultats mesurables dès les premières sessions de pratique guidée"},"variant":"gradient","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeRef":"lofi","themeMode":"named"}},{"id":"section-1771740503487","type":"clickfunnel-center-card","order":5,"design":{"media":{"overlayImage":"","overlayTarget":"section"},"colors":{"navBg":"#93C5FD","cardBg":"#FFFFFF","mediaBg":"#E5E7EB","navText":"#1F2937","buttonBg":"#F59E0B","buttonText":"#ffffff","navActiveText":"#1F2937","decorLeftColor":"#DC2626","decorRightColor":"#F59E0B","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"0px","marginBottom":"0px","paddingBottom":"0px"},"background":{"type":"image","value":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772267189495-j0w2ri.jpg","opacity":0.4},"typography":{"fontSize":"1rem","fontFamily":"inherit","lineHeight":"1.5","highlightColor":"#000000"}},"content":{"navItems":[{"label":"Entrepreneur","title":"Pour l''Entrepreneur","mediaUrl":"","subtitle":"Levée de fonds & vision","highlight":"Inspirez confiance aux investisseurs","mediaType":"","buttonText":"Je réussis ma levée de fonds","description":"Réussissez votre levée de fonds en apprenant à parler en public avec une vision qui inspire confiance et sécurité aux investisseurs les plus exigeants."},{"label":"Manager","title":"Pour le Manager","mediaUrl":"","subtitle":"Leadership & mobilisation","highlight":"Fédérez vos équipes avec charisme","mediaType":"","buttonText":"Je mobilise mes équipes","description":"Mobilisez vos troupes et fédérez vos équipes autour d''un projet commun en maîtrisant l''art de parler en public avec charisme et empathie."},{"label":"Expert Technique","title":"Pour l''Expert Technique","mediaUrl":"","subtitle":"Clarté & pédagogie","highlight":"Rendez vos données captivantes","mediaType":"","buttonText":"Je clarifie mon expertise","description":"Rendez vos données complexes accessibles et passionnantes pour tous en apprenant à parler en public avec une clarté et une pédagogie exemplaires."},{"label":"Étudiant","title":"Pour l''Étudiant","mediaUrl":"","subtitle":"Soutenances & jurys","highlight":"Transformez le stress en performance","mediaType":"","buttonText":"Je valide mes diplômes avec brio","description":"Validez vos diplômes avec brio en transformant votre stress de soutenance en une prestation orale fluide et convaincante face au jury."},{"label":"Leader","title":"Identité Élite","mediaUrl":"","subtitle":"Rejoignez le cercle des communicants","highlight":"Votre parole devient votre signature","mediaType":"","buttonText":"J''affirme mon leadership","description":"Ceux qui savent parler en public dirigent le monde et les entreprises. En choisissant cette voie, vous affirmez votre identité de leader. Parler en public devient votre signature, un avantage tactique majeur qui vous positionne immédiatement comme un expert incontesté."}],"showLeftDecor":true,"showRightDecor":true},"variant":"default","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeMode":"inherit"}},{"id":"section-1771743068973","type":"split-content-checklist","order":6,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"10px","marginBottom":"0px","paddingBottom":"10px"},"background":{"type":"color","value":""},"typography":{}},"content":{"image":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772234609438-38j5m.jpg","title":"La douleur du silence — Votre carrière mérite plus qu''un murmure","divider":true,"checklist":["Chaque réunion évitée est une promotion qui s''envole injustement","Le trac sabote votre image alors que votre expertise est réelle","Vos concurrents prennent la parole et occupent l''espace à votre place","Le coût psychologique de l''inaction dépasse largement le coût financier"],"description":"L''incapacité à parler en public est le plafond de verre le plus frustrant pour un professionnel talentueux et ambitieux. Chaque réunion évitée, chaque présentation ratée et chaque bafouillage est une opportunité de promotion qui s''envole injustement. La frustration de ne pas être entendu à sa juste valeur ronge votre confiance et limite votre impact réel."},"variant":"with-divider","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771751890794","type":"services-carousel","order":7,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"10px","marginBottom":"0px","paddingBottom":"10px"},"background":{"type":"color","value":""},"typography":{}},"content":{"title":"Fonctionnalités Clés","services":[{"icon":"","link":"","image":"","title":"Analyse par IA","linkText":"Je découvre l''outil IA","description":"Recevez un feedback immédiat sur votre débit et votre intonation pour parler en public de façon fluide. Un support visuel ne doit jamais remplacer votre capacité oratoire — il doit l''amplifier. Nous vous formons aussi à l''utilisation des outils modernes pour parler en public en mode hybride."},{"icon":"","link":"","image":"","title":"Simulateur de stress","linkText":"J''accède au simulateur","description":"Entraînez-vous dans des conditions réelles pour que parler en public devienne une seconde nature instinctive. Apprenez à gérer les imprévus techniques ou humains avec humour et professionnalisme. Une préparation solide sans support vous permet de traverser n''importe quel incident technique avec élégance."},{"icon":"","link":"","image":"","title":"Bibliothèque de pitchs","linkText":"J''explore la bibliothèque","description":"Utilisez des structures narratives prouvées pour parler en public sans jamais perdre le fil conducteur. Nous utilisons des schémas de storytelling éprouvés pour que parler en public devienne une expérience narrative captivante où vos idées s''enchaînent avec une fluidité naturelle mais stratégique."},{"icon":"","link":"","image":"","title":"Coaching en direct","linkText":"Je réserve mon coaching","description":"Échangez avec des experts pour affiner votre style unique et parler en public avec authenticité. Gardez votre calme et votre assurance lorsque vous devez parler en public face à un contradicteur. La répartie s''apprend et se travaille comme n''importe quelle autre technique de communication."}],"showDots":true,"subtitle":"Les outils de votre réussite oratoire","description":"Une suite complète d''outils technologiques et pédagogiques pour accélérer votre progression et parler en public avec un impact immédiat et mesurable."},"variant":"default","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771741660353","type":"text-columns","order":8,"design":{"colors":{"buttonText":"#ffffff","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"10px","marginBottom":"0px","paddingBottom":"10px"},"background":{"type":"color","value":""},"typography":{}},"content":{"column1":"Notre méthode pour parler en public repose sur une stratégie d''ancrage physique et de structure mentale rigoureuse. Nous commençons par la maîtrise du souffle diaphragmatique, suivis par la construction d''un storytelling magnétique qui capture l''attention. Ensuite, nous travaillons votre gestuelle pour qu''elle renforce chaque mot, avant de finaliser par des simulations de haute intensité.","column2":"Psychologie du Leader — Le moment où vous décidez de parler en public avec assurance, tout votre paysage mental change radicalement. La peur se transforme en une excitation saine, un moteur de performance puissant. Vous ressentez une fierté immense en voyant l''adhésion dans les yeux de votre auditoire. C''est une libération émotionnelle qui impacte votre vie bien au-delà de la scène.","column3":"Market Fit — Dans un monde saturé d''informations, savoir parler en public est la compétence ultime pour se démarquer. Que vous soyez en visio-conférence ou sur une estrade, notre formation s''adapte aux nouveaux codes de communication hybrides. Nous répondons aux besoins des cadres qui doivent parler en public avec une clarté laser en un temps record.","ctaLink":"","ctaText":"Je commence ma transformation","introduction":"Le Processus Élite — Une méthode en quatre étapes pour parler en public"},"variant":"two-column","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771746516886","type":"process","order":9,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"steps":[{"title":"Accédez à la plateforme instantanément","number":"01","description":"Notre plateforme est conçue pour une prise en main instantanée, sans configuration complexe. Vous pouvez commencer à améliorer votre capacité à parler en public dès les cinq prochaines minutes."},{"title":"Suivez les premiers modules","number":"02","description":"Accédez aux premiers modules pour parler en public avec plus d''impact dès votre prochaine réunion d''équipe, sans stress inutile. La progression est structurée pour des résultats rapides et mesurables."},{"title":"Mesurez votre progression","number":"03","description":"Grâce à nos outils, vous visualisez l''évolution de votre taux de conviction et la clarté de votre message. Chaque session vous rapproche d''une maîtrise totale, transformant votre investissement en une ascension professionnelle fulgurante."}],"title":"Implémentation Immédiate","subtitle":"Un démarrage sans aucune friction — commencez en 5 minutes"},"variant":"vertical","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771742847008","type":"cta","order":10,"design":{"colors":{"buttonText":"#a3a3a3","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"64px","marginBottom":"0px","paddingBottom":"64px"},"background":{"type":"color","value":"#f2fdf9"},"typography":{"fontSize":"1rem","fontFamily":"inherit","lineHeight":"1.5"}},"content":{"headline":"Garantie de Succès — Zéro risque, tout à gagner","primaryCta":"Je passe à l''action maintenant","description":"Nous sommes si convaincus de notre méthode pour parler en public que nous supprimons tout risque pour vous. Si vous ne ressentez pas une augmentation drastique de votre aisance après les premières sessions, nous vous accompagnons personnellement jusqu''à l''obtention de résultats tangibles. Votre réussite oratoire est notre unique priorité absolue.","primaryLink":"","secondaryCta":"Je découvre la méthode complète","secondaryLink":""},"variant":"centered","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771746086872","type":"text-columns","order":11,"design":{"colors":{"buttonText":"#ffffff","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"10px","marginBottom":"0px","paddingBottom":"10px"},"background":{"type":"color","value":"#f2f2f2"},"typography":{}},"content":{"column1":"Nous ne nous contentons pas de vous apprendre à parler en public, nous suivons votre progression chiffrée. Grâce à nos outils, vous visualisez l''évolution de votre taux de conviction et la clarté de votre message. Chaque session vous rapproche d''une maîtrise totale, transformant votre investissement en une ascension professionnelle fulgurante et mesurable.","column2":"Avantage Tactique — Chaque prise de parole est un événement stratégique que vous devez dominer. Apprendre à parler en public avec nous, c''est acquérir une répartie infaillible face aux questions difficiles. Vous apprenez à retourner les situations tendues à votre avantage, faisant de chaque occasion de parler en public une victoire tactique pour vos projets.","column3":"Le Futur de votre Voix — Imaginez-vous dans six mois, montant sur scène pour parler en public devant 500 personnes. Vous êtes calme, votre voix est assurée, votre message est limpide. Les applaudissements ne sont plus un rêve, mais la conséquence logique de votre maîtrise. Savoir parler en public vous ouvre des portes dont vous n''osiez même pas rêver aujourd''hui.","ctaLink":"","ctaText":"Je visualise mon succès","introduction":"Suivi du ROI — Mesurer votre impact réel"},"variant":"two-column","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771741864190","type":"services-grid","order":12,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"title":"Les dimensions clés de la maîtrise oratoire","services":[{"icon":"","link":"","title":"Gestion du Regard","linkText":"J''explore ce module","description":"Apprenez les techniques de balayage visuel pour que parler en public crée un lien fort avec votre audience. Le regard crée le lien — sans contact visuel, votre message perd 80% de sa force de persuasion. Apprenez à vous détacher de vos notes pour parler en public avec une liberté totale."},{"icon":"","link":"","title":"Maîtrise du Silence","linkText":"J''explore ce module","description":"Utilisez les pauses stratégiques pour parler en public avec une autorité naturelle et calme. Le silence permet de souligner un point important et donne à l''auditoire le temps d''intégrer vos paroles les plus fortes. Une conclusion doit toujours comporter un appel à l''action clair ou une pensée finale gravée dans les esprits."},{"icon":"","link":"","title":"Analyse de l''Auditoire","linkText":"J''explore ce module","description":"Adapter son langage est essentiel pour bien parler en public. Nous vous aidons à décrypter les attentes de votre public avant même de parler en public. L''interaction est la clé d''une présentation réussie — parler en public devient une conversation bidirectionnelle où vous lisez les signaux non-verbaux pour ajuster votre discours."},{"icon":"","link":"","title":"Répartie et Questions","linkText":"J''explore ce module","description":"La session de questions-réponses est souvent la phase la plus redoutée. Nous vous préparons aux objections les plus fréquentes pour ne jamais être pris de court. Utilisez les questions pour renforcer vos messages clés et démontrer votre expertise sur le sujet traité avec brio."},{"icon":"","link":"","title":"Assertivité Orale","linkText":"J''explore ce module","description":"L''assertivité est l''équilibre parfait pour parler en public : savoir dire les choses avec fermeté tout en restant respectueux et ouvert au dialogue. Prenez votre place légitime lors des débats. Évitez les mots d''excuse qui affaiblissent votre posture — soyez direct, soyez vrai, soyez pleinement convaincu par vos propres paroles."}],"subtitle":"Chaque compétence travaillée en profondeur","description":"Une approche globale qui transforme tous les aspects de votre prise de parole pour un impact total et durable."},"variant":"minimal","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771741921089","type":"dropcap-services","order":13,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"20px","marginBottom":"0px","paddingBottom":"20px"},"background":{"type":"color","value":""},"typography":{}},"content":{"title":"Maîtrisez toutes les dimensions de votre éloquence","dropCap":"É","subtitle":"Des compétences travaillées en profondeur pour une transformation totale et durable","introText":"L''éloquence n''est pas un don, c''est une discipline. Chaque module de notre programme est conçu pour lever un verrou spécifique et vous propulser vers une maîtrise complète de la prise de parole en public.","signature":"La Méthode Élite","additionalText":"Ancrage Émotionnel — L''émotion est le moteur de la mémorisation. Pour bien parler en public, vous devez savoir susciter des sentiments qui ancreront vos messages clés dans l''esprit de vos auditeurs. Partagez votre passion avec sincérité : c''est votre énergie émotionnelle qui fera la différence entre un discours correct et une prestation magistrale. L''empathie vous permet d''ajuster votre ton en temps réel, créant une connexion durable que la simple transmission d''informations ne pourra jamais égaler.","serviceColumns":[{"items":["Maîtrise de la voix et du timbre pour inspirer confiance","Modulation du débit pour maintenir une attention constante","Projection vocale sans effort, même dans de grands espaces","Gestuelle et posture : incarner son message avec force","Mains comme outils de ponctuation et de connexion","Communication non-verbale en harmonie avec le discours","Maîtrise de l''espace scénique et déplacement intentionnel","Éliminer les tics nerveux qui polluent le message"],"title":"Compétences vocales & corporelles","ctaLink":"","ctaText":"J''accède aux modules vocaux"},{"items":["Structure narrative : construire un discours mémorable","Storytelling de marque : devenir le héros de son récit","Préparation mentale : le mindset de l''orateur d''élite","Gestion du stress : transformer l''anxiété en énergie","Rhétorique moderne : l''art de la persuasion efficace","Leadership et présence : inspirer par la simple parole","Éloquence digitale : briller derrière un écran","Outils technologiques au service du verbe"],"title":"Stratégie mentale & narrative","ctaLink":"","ctaText":"J''accède aux modules mentaux"}]},"variant":"with-signature","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771746460336","type":"process-steps-cards","order":14,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"56px","marginBottom":"0px","paddingBottom":"56px"},"background":{"type":"color","value":""},"typography":{}},"content":{"steps":[{"image":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1771740822268-rrhbzo.webp","title":"Ancrage physique et libération du trac","number":"01","description":"Maîtrise du souffle diaphragmatique, techniques de respiration flash pour réguler votre système nerveux en quelques secondes. Visualiser votre succès est une étape clé — en préparant votre cerveau positivement, vous réduisez l''impact des pensées limitantes."},{"image":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1772234609438-38j5m.jpg","title":"Construction d''un storytelling magnétique","number":"02","description":"Nous utilisons des structures narratives éprouvées pour que parler en public devienne une expérience captivante. Créez un arc narratif puissant pour chaque intervention : un voyage que vous proposez à votre audience, avec un début, un milieu et une fin mémorables."},{"image":"https://jpyzyxdmdqfujprgyndc.supabase.co/storage/v1/object/public/media/1e3aa8cc-2165-45da-b14a-d7993937454c/1771676918521-lvimy.png","title":"Simulations de haute intensité","number":"03","description":"Entraînement en conditions réelles pour que la maîtrise devienne une seconde nature. Nous vous préparons aux objections les plus fréquentes et aux imprévus techniques pour ne jamais être pris de court, avec humour et une élégance professionnelle irréprochable."}],"title":"Votre parcours vers l''éloquence","subtitle":"Trois phases pour une transformation complète et durable"},"variant":"minimal","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeRef":"none","themeMode":"named"}},{"id":"section-1771745857654","type":"text-columns","order":15,"design":{"colors":{"buttonText":"#ffffff","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"column1":"Chaque jour où vous remettez à plus tard l''apprentissage de parler en public est un jour de stagnation professionnelle. Vos concurrents, eux, n''attendent pas pour prendre la parole et occuper l''espace que vous laissez vacant.","column2":"Le coût de l''inaction n''est pas seulement financier, il est psychologique : c''est le regret de ne pas avoir osé parler en public quand l''opportunité se présentait. Votre expertise mérite d''être entendue à sa juste valeur.","column3":"Est-ce utile de se filmer pour parler en public ? C''est un outil de progression exceptionnel pour prendre conscience de ses tics et améliorer sa gestuelle rapidement. Commencez dès aujourd''hui — le seul mauvais moment est demain.","ctaLink":"","ctaText":"Je commence maintenant, sans attendre","introduction":"L''Urgence d''Agir — Le coût réel de l''inaction"},"variant":"centered","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771742845142","type":"cta","order":16,"design":{"colors":{"buttonText":"#9a9898","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"64px","marginBottom":"0px","paddingBottom":"64px"},"background":{"type":"color","value":""},"typography":{"fontSize":"1rem","fontFamily":"inherit","lineHeight":"1.5"}},"content":{"headline":"Projetez-vous dans votre nouvelle vie","primaryCta":"Je transforme ma prise de parole","description":"Imaginez-vous dans six mois, montant sur scène pour parler en public devant 500 personnes. Vous êtes calme, votre voix est assurée, votre message est limpide. Les applaudissements ne sont plus un rêve, mais la conséquence logique de votre maîtrise. Ce futur commence dès votre première session.","primaryLink":"","secondaryCta":"Je veux en savoir plus","secondaryLink":""},"variant":"centered","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeMode":"custom","customTokens":{"base-100":"#e3eeed"}}},{"id":"section-1771749141714","type":"cta","order":17,"design":{"colors":{"buttonText":"#9a9898","buttonBackground":"#000000"},"spacing":{"marginTop":"0px","paddingTop":"64px","marginBottom":"0px","paddingBottom":"64px"},"background":{"type":"color","value":""},"typography":{"fontSize":"1rem","fontFamily":"inherit","lineHeight":"1.5"}},"content":{"headline":"PASSEZ À L''ACTION — Votre éloquence d''élite vous attend","primaryCta":"Je rejoins le programme maintenant","description":"Chaque jour d''inaction est une opportunité perdue. Rejoignez le cercle des communicants d''exception et faites de votre voix votre atout stratégique numéro un.","primaryLink":"","secondaryCta":"Je découvre la garantie de succès","secondaryLink":""},"variant":"banner","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}},"themeConfig":{"themeRef":"none","themeMode":"named"}},{"id":"section-1771746500385","type":"process","order":18,"design":{"colors":{"accent":"#111827","iconColor":"#8da8e2"},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"steps":[{"title":"Maîtrise du souffle diaphragmatique","number":"01","description":"La respiration ventrale est la base. Elle permet de soutenir votre voix, de calmer votre rythme cardiaque instantanément et d''aborder chaque prise de parole avec une sérénité physique totale."},{"title":"Storytelling magnétique","number":"02","description":"Construction d''une structure narrative qui capture l''attention et ne la lâche plus. Savoir introduire et conclure sont les deux moments critiques — nous vous donnons les formules d''accroche qui garantissent un impact mémorable dès les premières secondes."},{"title":"Gestuelle au service du verbe","number":"03","description":"Votre corps doit parler avant même que vous ne commenciez. Nous vous enseignons les gestes ouverts qui favorisent la connexion et l''empathie avec votre public, et comment éviter les tics nerveux qui polluent votre message."},{"title":"Simulations de haute intensité","number":"04","description":"Des mises en situation réelles pour ancrer chaque compétence dans votre mémoire musculaire. Le simulateur de stress vous entraîne dans des conditions authentiques pour que parler en public devienne une seconde nature instinctive et sereine."}],"title":"Les 4 piliers de la méthode","subtitle":"Une stratégie d''ancrage physique et de structure mentale rigoureuse"},"variant":"grid","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771747291252","type":"faq","order":19,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"80px","marginBottom":"0px","paddingBottom":"80px"},"background":{"type":"color","value":""},"typography":{}},"content":{"faqs":[{"answer":"C''est une réaction biologique ancestrale liée à la peur du rejet. Notre méthode désactive ce mécanisme pour vous libérer totalement.","question":"Pourquoi est-il si difficile de parler en public ?"},{"answer":"Oui, en utilisant les bonnes techniques d''ancrage, vous constaterez des progrès majeurs dès votre première séance de pratique guidée avec nous.","question":"Peut-on vraiment apprendre à parler en public rapidement ?"},{"answer":"Absolument pas. L''éloquence est une compétence technique qui se travaille, exactement comme l''apprentissage d''un instrument ou d''un sport de haut niveau.","question":"Faut-il avoir un talent inné pour parler en public ?"},{"answer":"L''ancrage physique et la respiration ventrale permettent de stabiliser votre corps et d''éliminer ces manifestations physiques du stress très rapidement.","question":"Comment gérer les mains qui tremblent quand on doit parler en public ?"},{"answer":"Tout à fait, nous avons des modules dédiés aux spécificités de la prise de parole digitale pour garder un impact maximal.","question":"Votre formation aide-t-elle à parler en public en visioconférence ?"},{"answer":"La plupart de nos clients ressentent une bascule psychologique après seulement 10 heures de pratique structurée selon notre méthode.","question":"Combien de temps faut-il pour ne plus avoir peur de parler en public ?"},{"answer":"Nous utilisons des techniques de palais mental et de structures narratives simples qui facilitent une mémorisation naturelle et sans effort.","question":"Comment structurer un discours pour parler en public sans notes ?"},{"answer":"C''est l''un des meilleurs boosters de confiance. Maîtriser sa parole devant les autres transforme radicalement l''image que l''on a de soi.","question":"Est-ce que parler en public aide à la confiance en soi ?"},{"answer":"L''utilisation d''une accroche forte, comme une question ou une statistique surprenante, permet de saisir l''attention immédiatement.","question":"Quelle est la meilleure technique pour captiver quand on commence à parler en public ?"},{"answer":"La clé réside dans la maîtrise des points clés plutôt que dans l''apprentissage d''un texte par cœur, souvent trop risqué.","question":"Comment éviter les trous de mémoire pour parler en public sereinement ?"},{"answer":"Les introvertis font souvent les meilleurs orateurs car ils préparent mieux leur contenu et font preuve d''une écoute très fine.","question":"Peut-on parler en public si l''on est de nature introvertie ?"},{"answer":"Des exercices d''articulation quotidiens de quelques minutes permettent de gagner en fluidité et en impact vocal de manière très durable.","question":"Comment améliorer son débit vocal pour parler en public avec clarté ?"},{"answer":"L''empathie et la garde de son calme sont vos meilleures armes pour désamorcer les tensions et garder le contrôle.","question":"Comment gérer un public difficile quand on doit parler en public ?"},{"answer":"Le regard crée le lien. Sans contact visuel, votre audience décroche et votre message perd 80% de sa force de persuasion.","question":"Pourquoi le regard est-il crucial pour parler en public ?"},{"answer":"Le silence permet de souligner un point important et donne à l''auditoire le temps d''intégrer vos paroles les plus fortes.","question":"Comment utiliser le silence pour parler en public avec autorité ?"},{"answer":"Absolument, il n''est jamais trop tard pour reprendre le pouvoir sur sa communication et faire évoluer sa carrière professionnelle.","question":"Est-ce que parler en public s''apprend à tout âge ?"},{"answer":"La variation des tons, du volume et du rythme est essentielle pour maintenir l''éveil et l''intérêt de votre public.","question":"Comment ne pas être monotone quand on doit parler en public longtemps ?"},{"answer":"Une conclusion doit toujours comporter un appel à l''action clair ou une pensée finale qui reste gravée dans les esprits.","question":"Comment conclure efficacement après avoir fini de parler en public ?"},{"answer":"Ils sont utiles s''ils illustrent vos propos, mais ils ne doivent jamais devenir une béquille sur laquelle vous lisez votre texte.","question":"Faut-il utiliser des transparents pour parler en public ?"},{"answer":"La respiration ventrale est la base. Elle permet de soutenir votre voix et de calmer votre rythme cardiaque instantanément.","question":"Comment respirer pour parler en public sans s''essouffler ?"},{"answer":"Parler trop vite et éviter le regard du public sont les deux erreurs les plus fréquentes que nous corrigeons.","question":"Quelles sont les erreurs courantes quand on commence à parler en public ?"},{"answer":"L''humour et une préparation solide sans support permettent de traverser n''importe quel incident technique avec une grande élégance.","question":"Comment gérer l''imprévu technique pour parler en public sans paniquer ?"},{"answer":"Les pieds bien ancrés au sol et le buste ouvert sont les signes d''une posture de leader affirmé et serein.","question":"Comment se tenir pour parler en public avec charisme ?"},{"answer":"L''utilisation de connecteurs logiques simples aide votre public à suivre votre cheminement intellectuel sans aucun effort particulier.","question":"Comment articuler ses idées pour parler en public de façon logique ?"},{"answer":"L''authenticité est la clé. Nous vous aidons à découvrir vos forces naturelles plutôt qu''à copier un modèle préétabli.","question":"Comment trouver son propre style pour parler en public ?"},{"answer":"C''est un outil de progression exceptionnel pour prendre conscience de ses tics et améliorer sa gestuelle rapidement.","question":"Est-ce utile de se filmer pour parler en public ?"},{"answer":"En utilisant votre diaphragme comme résonateur, vous pouvez porter votre voix loin sans jamais forcer sur vos cordes vocales.","question":"Comment projeter sa voix pour parler en public sans micro ?"},{"answer":"Des exercices de respiration et des affirmations positives permettent de basculer dans un état de performance optimale.","question":"Comment gérer le trac de dernière minute avant de parler en public ?"},{"answer":"Oui, s''il est utilisé avec parcimonie et qu''il sert votre propos, l''humour est un excellent levier de connexion.","question":"Peut-on utiliser l''humour pour parler en public ?"},{"answer":"Le feedback de l''auditoire et le sentiment de satisfaction personnelle sont les meilleurs indicateurs de votre réussite oratoire.","question":"Comment savoir si l''on a réussi à bien parler en public ?"}],"title":"Foire Aux Questions","subtitle":"Toutes vos questions sur la méthode pour parler en public avec maîtrise"},"variant":"accordion","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}},{"id":"section-1771743565790","type":"footer","order":20,"design":{"colors":{},"spacing":{"marginTop":"0px","paddingTop":"0px","marginBottom":"0px","paddingBottom":"0px"},"background":{"type":"color","value":""},"typography":{}},"content":{"logo":"","columns":[{"links":[{"url":"","label":"Le processus Élite"},{"url":"","label":"Fonctionnalités clés"},{"url":"","label":"Garantie de succès"}],"title":"La méthode"},{"links":[{"url":"","label":"Pour l''Entrepreneur"},{"url":"","label":"Pour le Manager"},{"url":"","label":"Pour l''Expert Technique"}],"title":"Profils"},{"links":[{"url":"","label":"FAQ"},{"url":"","label":"Commencer maintenant"},{"url":"","label":"Contact"}],"title":"Ressources"}],"logoText":"Éloquence Élite","copyright":"© 2025 Éloquence Élite. Tous droits réservés.","description":"La méthode neuroscientifique pour maîtriser l''art de parler en public, captiver et convaincre en toute situation.","socialLinks":[{"url":"","platform":"linkedin"},{"url":"","platform":"youtube"},{"url":"","platform":"instagram"}]},"variant":"minimal","advanced":{"customCSS":"","animations":{},"cssClasses":[],"visibility":{"mobile":true,"tablet":true,"desktop":true}}}]'::jsonb, NULL, NULL, 'luxury', NULL);
